/**
 * QplsJS - Librería cliente-servidor P2P WebRTC optimizada para QPLS
 * Autor: Quail Software
 */
class QplsJS {
  constructor(config = {}) {
    this.maxReceptores = config.maxReceptores || 5;
    this.chunkSize = 65536; // 64 KB
    this.peer = null;
    this.streamActual = null;
    this.receptoresConectados = new Map();
    this.conexionReceptor = null;
    this.isEmisor = false;
    this.onEstadoChange = config.onEstadoChange || (() => {});
    this.onReceptoresChange = config.onReceptoresChange || (() => {});
    this.onStreamRemoto = config.onStreamRemoto || (() => {});
    this.onDatosRecibidos = config.onDatosRecibidos || (() => {});
  }

  async inicializarPeerJS() {
    if (window.Peer) return Promise.resolve();
    return new Promise((resolve, reject) => {
      const script = document.createElement('script');
      script.src = 'https://cdn.jsdelivr.net/npm/peerjs@1.5.4/dist/peerjs.min.js';
      script.onload = () => resolve();
      script.onerror = () => reject(new Error('Error cargando PeerJS'));
      document.head.appendChild(script);
    });
  }

  async iniciarEmisor(customId = null) {
    await this.inicializarPeerJS();
    this.isEmisor = true;
    const codigo = customId || 'qpls_app_' + Math.floor(1000 + Math.random() * 9000);
    
    this.peer = new Peer(codigo);
    
    this.peer.on('open', (id) => {
      this.onEstadoChange(`Listo (${id})`, id);
    });

    this.peer.on('connection', (conn) => {
      if (this.receptoresConectados.size >= this.maxReceptores && !this.receptoresConectados.has(conn.peer)) {
        conn.on('open', () => {
          conn.send({ t: 'rechazado', motivo: `Límite alcanzado (${this.maxReceptores} dispositivos)` });
          setTimeout(() => conn.close(), 250);
        });
        return;
      }

      const registro = { conn, call: null };
      this.receptoresConectados.set(conn.peer, registro);
      this.onReceptoresChange(this.receptoresConectados);
      this.onEstadoChange(`Receptor conectado (${this.receptoresConectados.size}/${this.maxReceptores})`);

      conn.on('open', () => {
        if (this.streamActual) {
          registro.call = this.peer.call(conn.peer, this.streamActual);
        }
      });

      conn.on('data', (msg) => {
        if (msg && msg.t === 'solicitar_archivo' && this.onSolicitudArchivo) {
          this.onSolicitudArchivo(msg.modo, conn);
        }
      });

      conn.on('close', () => {
        this.receptoresConectados.delete(conn.peer);
        this.onReceptoresChange(this.receptoresConectados);
        this.onEstadoChange(`Receptor desconectado (${this.receptoresConectados.size}/${this.maxReceptores})`);
      });
    });

    return codigo;
  }

  async iniciarReceptor(idEmisor) {
    await this.inicializarPeerJS();
    this.isEmisor = false;
    this.peer = new Peer();

    this.peer.on('open', () => {
      this.onEstadoChange(`Conectando a ${idEmisor}...`);
      this.conexionReceptor = this.peer.connect(idEmisor, { serialization: 'binary' });

      this.conexionReceptor.on('open', () => this.onEstadoChange(`Conectado a ${idEmisor}`));
      this.conexionReceptor.on('data', (data) => this.onDatosRecibidos(data));
      this.conexionReceptor.on('close', () => this.onEstadoChange('Desconectado del emisor'));
    });

    this.peer.on('call', (llamada) => {
      llamada.answer();
      llamada.on('stream', (streamRemoto) => this.onStreamRemoto(streamRemoto));
    });
  }

  difundir(paquete) {
    this.receptoresConectados.forEach((reg) => {
      if (reg.conn && reg.conn.open) reg.conn.send(paquete);
    });
  }

  enviarStreamATodos(stream) {
    this.streamActual = stream;
    this.receptoresConectados.forEach((reg, peerId) => {
      if (reg.call) reg.call.close();
      reg.call = this.peer.call(peerId, stream);
    });
  }

  detenerStream() {
    if (this.streamActual) {
      this.streamActual.getTracks().forEach(t => t.stop());
      this.streamActual = null;
    }
    this.receptoresConectados.forEach((reg) => {
      if (reg.call) {
        reg.call.close();
        reg.call = null;
      }
    });
  }

  expulsarDispositivo(peerId) {
    const reg = this.receptoresConectados.get(peerId);
    if (!reg) return;
    if (reg.call) reg.call.close();
    if (reg.conn) reg.conn.close();
    this.receptoresConectados.delete(peerId);
    this.onReceptoresChange(this.receptoresConectados);
  }

  async enviarArchivoChunks(archivo, conn, modo = 'descarga') {
    if (!conn || !conn.open) return;
    const total = Math.ceil(archivo.size / this.chunkSize);
    conn.send({ t: 'inicio_bin', n: archivo.name, m: archivo.type, total, modo });

    for (let i = 0; i < total; i++) {
      if (!conn.open) break;
      while (conn.dataChannel && conn.dataChannel.bufferedAmount > 1048576) {
        await new Promise(r => setTimeout(r, 20));
      }
      const slice = archivo.slice(i * this.chunkSize, (i + 1) * this.chunkSize);
      const buffer = await slice.arrayBuffer();
      conn.send(buffer);
    }
    if (conn.open) conn.send({ t: 'fin_bin', n: archivo.name, m: archivo.type, modo });
  }

  solicitarDescarga(modo = 'descarga') {
    if (this.conexionReceptor && this.conexionReceptor.open) {
      this.conexionReceptor.send({ t: 'solicitar_archivo', modo });
    }
  }
}